function run(){
  // Simulates the cycle-following strategy literally: each prisoner opens up to 50 boxes.
  const n = 100;
  return mc(40000, () => {
    const box = shuffle(range(0, n - 1));
    for (let p = 0; p < n; p++) {
      let b = p, found = false;
      for (let t = 0; t < n / 2; t++) { if (box[b] === p) { found = true; break; } b = box[b]; }
      if (!found) return 0;
    }
    return 1;
  });
}
